import { z } from "zod";

/**
 * Single source of truth for typed handoffs exchanged between execution nodes
 * (persisted in the handoffs table). The TypeScript types below are derived
 * with `z.infer` and re-exported from the package index, so the runtime
 * validator and the static types cannot drift.
 *
 * Note: `nodeTypeHint` and `stageId` are intentionally plain strings. Plans are
 * model-produced (hints are advisory, not guaranteed to be an
 * `ExecutionNodeType`), and synthesized reports use stage ids outside
 * `VerificationStageId` (e.g. "default").
 *
 * This module must only import zod (never "./index") to avoid an import cycle.
 */

export const handoffPayloadKindSchema = z.enum([
  "PlanSpec",
  "Findings",
  "Patch",
  "VerificationReport",
  "Summary",
  "Generic",
  "TestReport",
  "ResearchFinding",
]);

export const baseHandoffSchema = z.object({
  kind: handoffPayloadKindSchema,
  summary: z.string().optional(),
});

export const planSpecHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("PlanSpec"),
  steps: z.array(z.object({
    id: z.string(),
    description: z.string(),
    nodeTypeHint: z.string().optional(),
  })),
  rationale: z.string().optional(),
  tracks: z.array(z.object({
    title: z.string(),
    body: z.string().optional(),
  })).optional(),
  // Structured planning lists (optional for back-compat with older planners).
  // `dependsOn` + `blocking` make non-blocking features explicit: a feature with
  // no unmet dependency and `blocking !== true` is eligible for parallel (swarm) execution.
  features: z.array(z.object({
    id: z.string(),
    title: z.string(),
    description: z.string().optional(),
    dependsOn: z.array(z.string()).optional(),
    blocking: z.boolean().optional(),
    docsRequired: z.boolean().optional(),
  })).optional(),
  // Documentation tasks, optionally tied to a feature via `featureId`.
  documentation: z.array(z.object({
    id: z.string(),
    title: z.string(),
    target: z.string().optional(),
    featureId: z.string().optional(),
  })).optional(),
  // Blockers / risks. `hard` severity gates execution (routes to approval).
  blockers: z.array(z.object({
    id: z.string(),
    title: z.string(),
    severity: z.enum(["hard", "soft"]),
    detail: z.string().optional(),
    blocksFeatureIds: z.array(z.string()).optional(),
  })).optional(),
});

export const findingsHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("Findings"),
  findings: z.array(z.object({
    title: z.string(),
    body: z.string().optional(),
    source: z.string().optional(),
  })),
});

export const patchHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("Patch"),
  files: z.array(z.object({
    path: z.string(),
    diff: z.string().optional(),
    sizeBytes: z.number().optional(),
  })),
});

export const verificationHandoffStatusSchema = z.enum(["passed", "failed", "inconclusive", "not_applicable"]);

export const verificationReportHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("VerificationReport"),
  passed: z.boolean(),
  status: verificationHandoffStatusSchema.optional(),
  stages: z.array(z.object({
    stageId: z.string(),
    passed: z.boolean(),
    details: z.string().optional(),
  })),
});

export const summaryHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("Summary"),
  body: z.string(),
});

export const genericHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("Generic"),
  data: z.record(z.string(), z.unknown()),
});

export const testReportHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("TestReport"),
  passed: z.boolean(),
  status: verificationHandoffStatusSchema.optional(),
  failures: z.array(z.object({
    test: z.string(),
    message: z.string().optional(),
  })).default([]),
});

export const researchFindingHandoffSchema = baseHandoffSchema.extend({
  kind: z.literal("ResearchFinding"),
  tracks: z.array(z.object({
    title: z.string(),
    body: z.string().optional(),
    source: z.string().optional(),
  })),
});

export const handoffPayloadSchema = z.discriminatedUnion("kind", [
  planSpecHandoffSchema,
  findingsHandoffSchema,
  patchHandoffSchema,
  verificationReportHandoffSchema,
  summaryHandoffSchema,
  genericHandoffSchema,
  testReportHandoffSchema,
  researchFindingHandoffSchema,
]);

/** Parsed (output) shapes, e.g. `TestReport.failures` is always present after parsing. */
export type HandoffPayloadKind = z.infer<typeof handoffPayloadKindSchema>;
export type BaseHandoffPayload = z.infer<typeof baseHandoffSchema>;
export type PlanSpecHandoff = z.infer<typeof planSpecHandoffSchema>;
export type FindingsHandoff = z.infer<typeof findingsHandoffSchema>;
export type PatchHandoff = z.infer<typeof patchHandoffSchema>;
export type VerificationReportHandoff = z.infer<typeof verificationReportHandoffSchema>;
export type SummaryHandoff = z.infer<typeof summaryHandoffSchema>;
export type GenericHandoff = z.infer<typeof genericHandoffSchema>;
export type TestReportHandoff = z.infer<typeof testReportHandoffSchema>;
export type ResearchFindingHandoff = z.infer<typeof researchFindingHandoffSchema>;
/** Tagged payload exchanged between execution nodes via the handoffs table. */
export type HandoffPayload = z.infer<typeof handoffPayloadSchema>;
/** Shape accepted by `handoffPayloadSchema.parse` (defaults not yet applied). */
export type HandoffPayloadInput = z.input<typeof handoffPayloadSchema>;
